def transform(grid):
    out=[r[:] for r in grid]
    h,w=len(grid),len(grid[0])
    for r in range(1,h-1):
        for c in range(1,w-1):
            if grid[r][c]==2 and all(grid[rr][cc]==3 for rr,cc in [(r-1,c-1),(r-1,c),(r-1,c+1),(r,c-1),(r,c+1),(r+1,c-1),(r+1,c),(r+1,c+1)]):
                for j in range(w):
                    if out[r][j]==0: out[r][j]=1
                for i in range(h):
                    if out[i][c]==0: out[i][c]=1
    return out
